    private static func draw_locator(_ context: CGContext) {
        // Same 24-point glyph grid, inset and optical weight as the other categories.
        context.saveGState()
        context.translateBy(x: 5, y: 5)
        context.scaleBy(x: 0.91667, y: 0.91667)
        context.setStrokeColor(UIColor.white.cgColor)
        context.setFillColor(UIColor.white.cgColor)
        context.setLineWidth(2.2)
        context.setLineCap(.round)
        context.strokeEllipse(in: CGRect(x: 4.5, y: 4.5, width: 15, height: 15))
        context.fillEllipse(in: CGRect(x: 8.7, y: 8.7, width: 6.6, height: 6.6))
        for (start, end) in [(CGPoint(x: 12, y: 2), CGPoint(x: 12, y: 6)),
                             (CGPoint(x: 12, y: 18), CGPoint(x: 12, y: 22)),
                             (CGPoint(x: 2, y: 12), CGPoint(x: 6, y: 12)),
                             (CGPoint(x: 18, y: 12), CGPoint(x: 22, y: 12))] {
            context.move(to: start)
            context.addLine(to: end)
            context.strokePath()
        }
        context.restoreGState()
    }

    private static func draw_cache(_ context: CGContext) {
        // A drive, on the same 24-point grid, inset and weight as the other categories: the body
        // in white, a slot line and two status lights cut out of it.
        context.saveGState()
        context.translateBy(x: 5, y: 5)
        context.scaleBy(x: 0.91667, y: 0.91667)
        let body = CGMutablePath()
        body.move(to: CGPoint(x: 6.2, y: 5))
        body.addLine(to: CGPoint(x: 17.8, y: 5))
        body.addCurve(to: CGPoint(x: 20.1, y: 6.6), control1: CGPoint(x: 18.9, y: 5), control2: CGPoint(x: 19.7, y: 5.6))
        body.addLine(to: CGPoint(x: 21.8, y: 12.2))
        body.addLine(to: CGPoint(x: 21.8, y: 16.6))
        body.addCurve(to: CGPoint(x: 19.4, y: 19), control1: CGPoint(x: 21.8, y: 17.9), control2: CGPoint(x: 20.7, y: 19))
        body.addLine(to: CGPoint(x: 4.6, y: 19))
        body.addCurve(to: CGPoint(x: 2.2, y: 16.6), control1: CGPoint(x: 3.3, y: 19), control2: CGPoint(x: 2.2, y: 17.9))
        body.addLine(to: CGPoint(x: 2.2, y: 12.2))
        body.addLine(to: CGPoint(x: 3.9, y: 6.6))
        body.addCurve(to: CGPoint(x: 6.2, y: 5), control1: CGPoint(x: 4.3, y: 5.6), control2: CGPoint(x: 5.1, y: 5))
        body.closeSubpath()
        context.setFillColor(UIColor.white.cgColor)
        context.addPath(body)
        context.fillPath()
        context.setBlendMode(.clear)
        context.setStrokeColor(UIColor.white.cgColor)
        context.setLineWidth(1.5)
        context.setLineCap(.round)
        context.move(to: CGPoint(x: 2.6, y: 12.2))
        context.addLine(to: CGPoint(x: 21.4, y: 12.2))
        context.strokePath()
        context.setFillColor(UIColor.white.cgColor)
        context.fillEllipse(in: CGRect(x: 15.6, y: 14.6, width: 2.2, height: 2.2))
        context.fillEllipse(in: CGRect(x: 18.4, y: 14.6, width: 2.2, height: 2.2))
        context.restoreGState()
    }

    static func image(named name: String, side: CGFloat = 30) -> UIImage? {
        guard side > 0 else { return nil }
        let key = "\(name)|\(side)"
        if let image = cache[key] { return image }
        let colors: [CGColor]
        let draw: (CGContext) -> Void
        switch name {
        case "app-badge":
            colors = [UIColor(red: 1, green: 0.48, blue: 0.66, alpha: 1).cgColor, UIColor.systemPink.cgColor]
            draw = SolvgramBadgeArtwork.drawSettingsIcon
        case "privacy":
            colors = [UIColor(red: 0.2627451, green: 0.7254902, blue: 1, alpha: 1).cgColor, UIColor(red: 0, green: 0.5215686, blue: 0.945098, alpha: 1).cgColor]
            draw = draw_privacy
        case "messages":
            colors = [UIColor(red: 0.2627451, green: 0.7254902, blue: 1, alpha: 1).cgColor, UIColor(red: 0, green: 0.5215686, blue: 0.945098, alpha: 1).cgColor]
            draw = draw_messages
        case "chat-list":
            colors = [UIColor(red: 0.2627451, green: 0.7254902, blue: 1, alpha: 1).cgColor, UIColor(red: 0, green: 0.5215686, blue: 0.945098, alpha: 1).cgColor]
            draw = draw_chat_list
        case "chats":
            colors = [UIColor(red: 0.3803922, green: 0.8745098, blue: 0.5254902, alpha: 1).cgColor, UIColor(red: 0.1607843, green: 0.7411765, blue: 0.3254902, alpha: 1).cgColor]
            draw = draw_chats
        case "message-menu":
            colors = [UIColor(red: 0.6588235, green: 0.5411765, blue: 0.9803922, alpha: 1).cgColor, UIColor(red: 0.4705882, green: 0.3333333, blue: 0.8509804, alpha: 1).cgColor]
            draw = draw_message_menu
        case "stories":
            colors = [UIColor(red: 1, green: 0.4705882, blue: 0.4901961, alpha: 1).cgColor, UIColor(red: 0.9411765, green: 0.2666667, blue: 0.3254902, alpha: 1).cgColor]
            draw = draw_stories
        case "media":
            colors = [UIColor(red: 1, green: 0.7843137, blue: 0.3529412, alpha: 1).cgColor, UIColor(red: 0.9647059, green: 0.6470588, blue: 0.1019608, alpha: 1).cgColor]
            draw = draw_media
        case "translation-voice":
            colors = [UIColor(red: 0.6588235, green: 0.5411765, blue: 0.9803922, alpha: 1).cgColor, UIColor(red: 0.4705882, green: 0.3333333, blue: 0.8509804, alpha: 1).cgColor]
            draw = draw_translation_voice
        case "profiles":
            colors = [UIColor(red: 0.3215686, green: 0.8470588, blue: 0.8627451, alpha: 1).cgColor, UIColor(red: 0.0941176, green: 0.6862745, blue: 0.7254902, alpha: 1).cgColor]
            draw = draw_profiles
        case "cache":
            colors = [UIColor(red: 0.3215686, green: 0.8470588, blue: 0.8627451, alpha: 1).cgColor, UIColor(red: 0.0941176, green: 0.6862745, blue: 0.7254902, alpha: 1).cgColor]
            draw = draw_cache
        case "locator":
            colors = [UIColor(red: 0.3215686, green: 0.8470588, blue: 0.8627451, alpha: 1).cgColor, UIColor(red: 0.0941176, green: 0.6862745, blue: 0.7254902, alpha: 1).cgColor]
            draw = draw_locator
        case "calls-notifications":
            colors = [UIColor(red: 1, green: 0.4, blue: 0.4196078, alpha: 1).cgColor, UIColor(red: 0.9490196, green: 0.1764706, blue: 0.2392157, alpha: 1).cgColor]
            draw = draw_calls_notifications
        case "appearance":
            colors = [UIColor(red: 1, green: 0.5098039, blue: 0.7019608, alpha: 1).cgColor, UIColor(red: 0.9333333, green: 0.2980392, blue: 0.5686275, alpha: 1).cgColor]
            draw = draw_appearance
        case "location":
            colors = [UIColor(red: 1, green: 0.7843137, blue: 0.3529412, alpha: 1).cgColor, UIColor(red: 0.9647059, green: 0.6470588, blue: 0.1019608, alpha: 1).cgColor]
            draw = draw_location
        case "accounts":
            colors = [UIColor(red: 0.4784314, green: 0.6431373, blue: 1, alpha: 1).cgColor, UIColor(red: 0.2980392, green: 0.4588235, blue: 0.8745098, alpha: 1).cgColor]
            draw = draw_accounts
        case "voice":
            colors = [UIColor(red: 1, green: 0.7843137, blue: 0.3529412, alpha: 1).cgColor, UIColor(red: 0.9647059, green: 0.6470588, blue: 0.1019608, alpha: 1).cgColor]
            draw = draw_voice
        case "ghost":
            colors = [UIColor(red: 0.6588235, green: 0.5411765, blue: 0.9803922, alpha: 1).cgColor, UIColor(red: 0.4705882, green: 0.3333333, blue: 0.8509804, alpha: 1).cgColor]
            draw = draw_ghost
        default: return nil
        }
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: side, height: side))
        let image = renderer.image { renderer in
            let context = renderer.cgContext
            context.scaleBy(x: side / 32, y: side / 32)
            context.saveGState()
            context.addEllipse(in: CGRect(x: 0, y: 0, width: 32, height: 32))
            context.clip()
            if let gradient = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: colors as CFArray, locations: [0, 1]) {
                context.drawLinearGradient(gradient, start: .zero, end: CGPoint(x: 0, y: 32), options: [])
            }
            context.restoreGState()
            context.beginTransparencyLayer(auxiliaryInfo: nil)
            draw(context)
            context.endTransparencyLayer()
        }
        cache[key] = image
        return image
    }
}
